using System.Collections.Generic;
using Microsoft.Web.Administration;
using Microsoft.Web.Management.Server;
namespace JexusManager.Features.IsapiFilters { internal sealed class IsapiFiltersService : ModuleService { [ModuleServiceMethod] public IsapiFiltersItem[] GetItems() { var result = new List<IsapiFiltersItem>(); foreach (ConfigurationElement e in Collection()) result.Add(new IsapiFiltersItem { Name = (string)e["name"], Path = (string)e["path"], PreConditions = new List<string>(((string)e["preCondition"]).Split(',')), EnableCache = (bool)e["enableCache"], Flag = e.IsLocallyStored ? "Local" : "Inherited" }); return result.ToArray(); } [ModuleServiceMethod] public void Add(IsapiFiltersItem item) { AddItem(Collection(), item); ManagementUnit.Update(); } [ModuleServiceMethod] public void Update(IsapiFiltersItem oldItem, IsapiFiltersItem item) { var c = Collection(); var e = Find(c, oldItem); if (e != null) c.Remove(e); AddItem(c, item); ManagementUnit.Update(); } [ModuleServiceMethod] public void Remove(IsapiFiltersItem item) { var e = Find(Collection(), item) ?? throw new System.InvalidOperationException("ISAPI filter was not found."); Collection().Remove(e); ManagementUnit.Update(); } private ConfigurationElementCollection Collection() => ManagementUnit.Configuration.GetSection("system.webServer/isapiFilters").GetCollection(); private static ConfigurationElement Find(ConfigurationElementCollection c, IsapiFiltersItem item) { foreach (ConfigurationElement e in c) if ((string)e["name"] == item.Name) return e; return null; } private static void AddItem(ConfigurationElementCollection c, IsapiFiltersItem i) { if (i == null || string.IsNullOrWhiteSpace(i.Name)) throw new System.ArgumentException("A filter name is required."); var e = c.CreateElement(); e["name"] = i.Name; e["path"] = i.Path; e["preCondition"] = string.Join(",", i.PreConditions); e["enableCache"] = i.EnableCache; c.Add(e); } } }
